def my_sqrt(x):
    i = 0
    while i * i <= x:
        i += 1                  # keep counting up as long as squaring still fits within x
    return i - 1               # step back one, since i just overshot past the answer


if __name__ == "__main__":
    x = 8
    print(my_sqrt(x))

