def my_sqrt(x):
    if x < 2:
        return x                  # 0 and 1 are already their own square roots
    lo, hi = 1, x // 2            # the answer for x >= 4 can never exceed x divided by 2
    while lo <= hi:
        mid = (lo + hi) // 2
        if mid * mid == x:
            return mid              # found the exact square root
        elif mid * mid < x:
            lo = mid + 1             # mid is too small, search the upper half
        else:
            hi = mid - 1             # mid is too big, search the lower half
    return hi                     # hi lands on the largest value whose square did not exceed x


if __name__ == "__main__":
    x = 8
    print(my_sqrt(x))

