def my_sqrt(x):
    if x < 2:
        return x                  # 0 and 1 are already their own square roots
    guess = x
    while guess * guess > x:
        guess = (guess + x // guess) // 2  # Newton's method: average the guess with x divided by the guess
    return guess                 # once squaring no longer overshoots, guess is the floor of the square root


if __name__ == "__main__":
    x = 8
    print(my_sqrt(x))

